TLM.f("Sancti/12-08",{"officium":"In Conceptione Immaculata Beatæ Mariæ Virginis","rule":["ex C11;","Gloria","Credo","Prefatio=Maria=Conceptióne immaculáta;"],"ruleInherited":["Gloria","Credo","Prefatio=Maria=Festivitate","Gloria","Suffr=Spiritu;Ecclesiæ,Papa;;","Prefatio=Maria=veneratione;"],"fallback":"Commune/C11","sections":{"Introitus":[{"k":"ref","la":"Is 61:10"},{"k":"text","la":"Gaudens gaudébo in Dómino, et exsultábit ánima mea in Deo meo: quia índuit me vestiméntis salútis: et induménto justítiæ circúmdedit me, quasi sponsam ornátam monílibus suis."},{"k":"ref","la":"Ps 29:2"},{"k":"text","la":"Exaltábo te, Dómine, quóniam suscepísti me: nec delectásti inimícos meos super me."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Gaudens gaudébo in Dómino, et exsultábit ánima mea in Deo meo: quia índuit me vestiméntis salútis: et induménto justítiæ circúmdedit me, quasi sponsam ornátam monílibus suis."}],"Oratio":[{"k":"text","la":"Deus, qui per immaculátam Vírginis Conceptiónem dignum Fílio tuo habitáculum præparásti: quǽsumus; ut, qui ex morte ejúsdem Filii tui prævísa eam ab omni labe præservásti, nos quoque mundos ejus intercessióne ad te perveníre concédas."},{"k":"macro","name":"Per eundem"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"rubric","la":"Prov 8:22-35"},{"k":"text","la":"Dóminus possedit me in inítio viárum suárum, ántequam quidquam fáceret a princípio. Ab ætérno ordináta sum, et ex antíquis, ántequam terra fíeret. Nondum erant abýssi, et ego jam concépta eram: necdum fontes aquárum erúperant: necdum montes gravi mole constíterant: ante colles ego parturiébar: adhuc terram non fécerat et flúmina et cárdines orbis terræ. Quando præparábat cœlos, áderam: quando certa lege et gyro vallábat abýssos: quando æthera firmábat sursum et librábat fontes aquárum: quando circúmdabat mari términum suum et legem ponébat aquis, ne transírent fines suos: quando appendébat fundaménta terræ. Cum eo eram cuncta compónens: et delectábar per síngulos dies, ludens coram eo omni témpore: ludens in orbe terrárum: et delíciæ meæ esse cum filiis hóminum. Nunc ergo, filii, audíte me: Beáti, qui custódiunt vias meas. Audíte disciplínam, et estóte sapiéntes, et nolíte abjícere eam. Beátus homo, qui audit me et qui vígilat ad fores meas cotídie, et obsérvat ad postes óstii mei. Qui me invénerit, invéniet vitam et háuriet salútem a Dómino."}],"Graduale":[{"k":"ref","la":"Judith 13:23"},{"k":"text","la":"Benedícta es tu. Virgo María, a Dómino, Deo excélso, præ ómnibus muliéribus super terram."},{"k":"ref","la":"Judith 15:10"},{"k":"text","la":"Tu glória Jerúsalem, tu lætítia Israël, tu honorificéntia pópuli nostri. Allelúja, allelúja."},{"k":"ref","la":"Cant 4:7"},{"k":"text","la":"Tota pulchra es, María: et mácula originális non est in te. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Judith 15:10"},{"k":"text","la":"Tu glória Jerúsalem, tu lætítia Israël, tu honorificéntia pópuli nostri."},{"k":"ref","la":"Cant 4:7"},{"k":"text","la":"Tota pulchra es, María: et mácula originális non est in te. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 86:1-2"},{"k":"text","la":"Fundaménta ejus in móntibus sanctis: díligit Dóminus portas Sion super ómnia tabernácula Jacob."},{"k":"ref","la":"Ps 85:3"},{"k":"text","la":"Gloriósa dicta sunt de te, cívitas Dei."},{"k":"ref","la":"Ps 86:5"},{"k":"text","la":"Homo natus est in ea, et ipse fundávit eam Altíssimus."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 1:26-28"},{"k":"text","la":"In illo témpore: Missus est Angelus Gábriël a Deo in civitátem Galilææ, cui nomen Názareth, ad Vírginem desponsátam viro, cui nomen erat Joseph, de domo David, et nomen Vírginis María. Et ingréssus Angelus ad eam, dixit: Ave, grátia plena; Dóminus tecum: benedícta tu in muliéribus."}],"Offertorium":[{"k":"ref","la":"Luc 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus, allelúja."}],"Secreta":[{"k":"text","la":"Salutárem hóstiam, quam in sollemnitáte immaculátæ Conceptiónis beátæ Vírginis Maríæ tibi, Dómine, offérimus, súscipe et præsta: ut, sicut illam tua grátia præveniénte ab omni labe immúnem profitémur; ita ejus intercessióne a culpis ómnibus liberémur."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 86:3, Luc 1:49"},{"k":"text","la":"Gloriósa dicta sunt de te, María: quia fecit tibi magna qui potens est."}],"Postcommunio":[{"k":"text","la":"Sacraménta quæ súmpsimus, Dómine, Deus noster: illíus in nobis culpæ vúlnera réparent; a qua immaculátam beátæ Maríæ Conceptiónem singuláriter præservásti."},{"k":"macro","name":"Per Dominum"}]},"hr":{"13fb0642d0068251":{"t":"Iz 61, 10, Ps 29, 2\n(Iz 61, 10) Kličem od radosti u Gospodinu i duša se moja veseli u Bogu mojemu, jer me je odjenuo u haljine spasenja i ogrnuo me plaštem svetosti, kao zaručnicu urešenu biserima. (Ps 29, 2) Veličat ću te, Gospodine, jer si me odabrao. Nisi dao da se moji neprijatelji raduju nada mnom.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Iz 61, 10) Kličem od radosti u Gospodinu i duša se moja veseli u Bogu mojemu, jer me je odjenuo u haljine spasenja i ogrnuo me plaštem svetosti, kao zaručnicu urešenu biserima.","kn":"(Izai. 6, 1, 10). Radujem ee u Gospodinu i moja ;se duša veseli mome Bogu, jer me je odjenuo u haljine spasenja i ogrnuo plaštem svetosti, kao zaručnicu u njezinu nakitu. (Ps. 29, 2). Veličam Te, Gospodine, jer si me oslobodio i jer nijesi dao da se moji neprijatelji raduju nada mnom. Slava Ocu . . . Radujem se . . .","knRef":"Kniewald 1942, str. 454–455 (snimka 228) (OCR)"},"ab40f9cbf311caa8":{"t":"<i>Pomolimo se</i>.\nBože, koji si bezgrješnim Začećem Djevice pripravio dostojno prebivalište svojemu Sinu, molimo da ti, koji si je očuvao od svake ljage, predvidjevši smrt svoga Sina, podaš da i mi njezinim zagovorom dođemo k tebi čisti.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Bože, koji si neoskvrnjenim začećem blažene Djevice pripravio dostojno prebivalište svome Sinu, kao što si predvldjevši smrt svoga Sina Njegovu djevičansku Majku očuvao od svake ljage, tako da dopustiš, te i mi njezinim za Bezgrješno Začeće BI. DJ. M. 8. XII, govorom očišćeni dođemo k Tebi, po istom Gospodinu našemu ...","knRef":"Kniewald 1942, str. 454–455 (snimka 228) (OCR)"},"12e5755cdaafa4c3":{"t":"Izr 8, 22-35\nČitanje Knjige Mudrosti: Gospodin me je imao u početku svojih putova, prije nego je išta učinio. Bila sam oduvijek određena, prije postanka zemlje. Još nije bilo bezdana, a ja sam već bila začeta. Izvori voda još nisu bili provreli, planine nisu postojale, rodila sam se prije bregova. Još nije bio stvorio ni Zemlju, ni rijeke, niti postavio zemaljske stožere, a ja sam postojala. Kad je pripremao svod, kad je stalnim zakonom postavljao međaše bezdanima, kad je gore učvršćivao zrak i dolje pokretao izvore voda, kad je unaokolo udarao granice moru i postavljao zakone vodama da se ne prelijevaju izvan svojih korita, kad je stavljao osnove zemlji, bila sam s njime i svime upravljala. Radovala sam se svakog dana, igrala sam pred njim čitavo vrijeme, igrala sam po zemaljskom krugu i užitak mi je biti s ljudima. Zato me, djeco, čujte! Blago onima koji idu mojim putovima. Slušajte nauku, budite mudri, nemojte je odbaciti. Blago čovjeku koji mene sluša i koji svaki dan bdije uz moja vrata i čuva ulaze u moj dom. Tko mene nađe naći će život i primit će spasenje od Gospodina.","kn":"Čitanje knjige Mudrosti (Posl. 8, 22-35). Gospodin me je imao u početku svojih puteva, prije nego je išta učinio na jpočetku. Bila sam određena od vijeka i od davnina prije nego je postala zemlja. Još nije bilo bezdana, a, ja sam već bila začeta, izvori voda još nijesu provalili, niti su postojali golemi skupovi gora: rodila sam se prije bregova. Još nije bio učinio ni zemlje ni rijeka -ni zemaljskih stožera. BUa sam tu, kad je pripravljao nebo, kad je stalnim zakonom i međom ograđivao bezdane, kad je gore učvršćivao uzduh i premjerao vodene izvore, kad je okolo udario granice moru, postavljao zakone vodama, da ne bi prelazile svojih međa, kad je postavljao temelje zemlje. Bila sam s njim i upravljala sam svim stvarima i veselila sai* se sve dane i sve vrijeme igrala sam se pred njim, igrala sam se, na zemaljskoj kugli, jer je moj užitak boraviti sa sinovima ljudskim. Zato me, djeco, poslušajte: Blago onima, koji idu mojim putevlma! Slušajte moju nauku i budite mudri 1 .nemojte je odbaciti. Blago čovjeku, koji me sluša i koji uvijek bdije uz moja vrata i čuva ulaze u moju kuću. Tko nađe mene, naći će život i iprimit će spas od Gospodina!","knRef":"Kniewald 1942, str. 454–455 (snimka 228) (OCR)"},"43384be4b6b52a2d":{"t":"Jdt 13, 23 i 15, 10\nBlagoslovljena si, Djevo Marijo, od Gospodina Boga Svevišnjega nad sve žene na zemlji. Ti si slava Jeruzalema, ti si radost Izraela, ti dika puka našega.\n\nPj 4, 7\n<i>Aleluja</i>, <i>aleluja</i>.\nSva si lijepa, o Marijo, i ljage istočne nema na tebi. <i>Aleluja</i>.","kn":"(Judit. 13, 23; 15, 10). Blagoslovena si, Djevo Marijo, nad sve žene na zemlji. Ti si slava Jeruzalema, Ti si veselje Izraela, Ti si ponos našega naroda.\n\nAleluja, aleluja. (Ca.nt. 4, 7). Sva si lijepa, o Marijo, i istočne ljage nema u Tebi, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 454–455 (snimka 228) (OCR)"},"610f4dae5874559b":{"t":"Lk 1, 26-28\nSlijedi sveto Evanđelje po Luki. U ono vrijeme: Posla Bog anđela Gabrijela u galilejski grad Nazaret k djevici Mariji, koja je bila zaručena s Davidovim potomkom Josipom. Anđeo uđe k njoj i reče: Zdravo, milosti puna, Gospodin s tobom, blagoslovljena ti među ženama!","kn":"t Slijedi sveto evanđelje po Luki (1, 26-28). U ono vrijeme posla Bog anđela Gabriela u galilejski grad Nazaret k djevici, zaručenoj s mužem, koji se zvao Josip iz kuće Davidove, a djevica se zvaia Marija. Kad je anđeo k njoj ušao, reče: Zdravo milosti puna, Gospodin iS tobom, blagoslovljena ti među ženama!","knRef":"Kniewald 1942, str. 456–457 (snimka 229) (OCR)"},"115977479ad745cb":{"t":"Lk 1, 28\nZdravo Marijo, milosti puna, Gospodin s tobom, blagoslovljena ti među ženama, aleluja.","kn":"(Lk. 1, 28). Zdravo MarijO', milosti puna, Gospodin s tobom, blagoslovljena ti među ženama! Aleluja.","knRef":"Kniewald 1942, str. 456–457 (snimka 229) (OCR)"},"df90c277f899a6f7":{"t":"Primi, Gospodine, spasonosnu žrtvu, koju ti prinosimo o svetkovini bezgrješnog Začeća blažene djevice Marije, i podaj da se njezinim zagovorom onako izbavimo od svojih krivica kako priznajemo da je ona tvojom milošću od svake ljage unaprijed bila sačuvana.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, Gospodine spasonosnu žrtvu, što je prinosimo o svetkovini neoskvrnjenoga začeća blažene djevice Marije i podaj, da nas, koji jp.riznajemo^, da si je svojom milošću unapred oslobodio od svake ljage, njezin zagovor izbavi od svake krivice; po G. n.","knRef":"Kniewald 1942, str. 456–457 (snimka 229) (OCR)"},"a908da632a671b33":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože: i da te <i>o bezgrešnom začeću</i> blažene Marije vazda Djevice hvalimo, blagoslivljamo i slavimo. Ona je osjenjena Duhom Svetim začela jedinorođenoga Sina tvoga i sačuvavši slavu djevičanstva prosula svijetom vječno svjetlo Isusa Krista Gospodina našega. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, da uvijek i, svagdje Tebi, Gospodine sveti. Oče svemogući, vječni Bože, zahvaljujemo i da Te hvalimo, slavimo i uzvisujemo o (Pohodu, Prikazanju, Bezgrješnom Začeću, Navještenju, Uznesenju. Rođenju, svetkovini) blažene Marije, vazda Djevice, koja je po Duhu Svetom začela jedinorođenoga Tvoga Sina i zadržavši slavu djevičanstva dala svijetu vječno svijetlo, Isuisa Krista, Gospodina našega, po kome anđeli hvale Tvoje veličanstvo, klanjaju Ti se gospodstva, podlažu Ti se vlasti, slave Te nebesa i nebeske sile s blaženim Serafinima kličući u zajedničkoj^ radosti. A mi Te molimo, da nam zapovjediš s njima sjediniti naše glasove smjerno ispovijedajući:","knRef":"Kniewald 1942, str. 22–23 (snimka 12) (OCR)"},"f711ace3bf06310d":{"t":"Veličanstveno je što je rečeno o tebi, Marijo, jer ti je Svemogući učinio velike stvari.","kn":". Valja da Te slavimo, o Djevice Marijo, jer Ti je svemogući učinio velike stvari.","knRef":"Kniewald 1942, str. 456–457 (snimka 229) (OCR)"},"60b92422f6fb624f":{"t":"<i>Pomolimo se</i>.\nOtajstva koja primismo, Gospodine Bože naš, iscijelila u nama rane onoga grijeha od kojega si divno očuvao bezgrješno Začeće blažene Marije.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine, Bože naš, da otajstva, što smo ih primili, izliječe u nama rane '0.n'0'@a grijeha, od koga si divnom povlasticom očuvao neoskvrnjeno začeće Blažene Djevice Marije, po G. n. I, K.","knRef":"Kniewald 1942, str. 456–457 (snimka 229) (OCR)"}}});
